def build(ev):
    """Converts R into ev(...) records (ev is passed in from seed_events)."""
    out = []
    for (slug, start, venue, cat, dur, price, vip, country, featured, occ, mk, en) in R:
        seating = "general" if price == 0 else None
        out.append(ev(slug, 2026, cat, venue, start, dur, price, vip, country, [], mk, en,
                      featured=featured, occ=occ, seating=seating))
    return out
